# Let me manually compare character by character
inputs = ['dxgzaf', 'vkwa', 'beaddh', 'hhyyi', 'ibh']
outputs = ['dxgzaf', 'vkwa', 'bzavaddh', 'hhfkfkf', 'fbh']

print("Detailed character comparison:")
for i in range(len(inputs)):
    inp = inputs[i]
    outp = outputs[i]
    print(f"\n{i}: '{inp}' -> '{outp}'")
    if inp != outp:
        print("  Characters that differ:")
        for j, (ch_in, ch_out) in enumerate(zip(inp, outp)):
            if ch_in != ch_out:
                print(f"    Position {j}: '{ch_in}' -> '{ch_out}'")
        # Check if one string is longer
        if len(inp) != len(outp):
            print(f"  Length difference: {len(outp)} vs {len(inp)}")
            if len(outp) > len(inp):
                print(f"  Extra chars in output: '{outp[len(inp):]}'")
            else:
                print(f"  Extra chars in input: '{inp[len(outp):]}'")

